import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Direct Preference Optimization of Video Large Multimodal Models from Language Model Reward","description":"","frontmatter":{"title":"Direct Preference Optimization of Video Large Multimodal Models from Language Model Reward","arxiv":"2404.01258","date":"2024-04-01","authors":"Ruohong Zhang, Liangke Gui, Zhiqing Sun, Yihao Feng, Keyang Xu, Yuanhan Zhang, Di Fu, Chunyuan Li, Alexander Hauptmann, Yonatan Bisk, Yiming Yang","categories":"cs.CV, cs.AI","topics":"视频大模型对齐, DPO, 奖励建模","outline":[2,2]},"headers":[],"relativePath":"papers/2404.01258.md","filePath":"papers/2404.01258.md","lastUpdated":null}'),e={name:"papers/2404.01258.md"};function l(i,s,m,r,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="direct-preference-optimization-of-video-large-multimodal-models-from-language-model-reward" tabindex="-1">Direct Preference Optimization of Video Large Multimodal Models from Language Model Reward <a class="header-anchor" href="#direct-preference-optimization-of-video-large-multimodal-models-from-language-model-reward" aria-label="Permalink to &quot;Direct Preference Optimization of Video Large Multimodal Models from Language Model Reward&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2404.01258" target="_blank" rel="noreferrer">2404.01258</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-04-01（v2: 2024-04-02）</td></tr><tr><td><strong>作者</strong></td><td>Ruohong Zhang, Liangke Gui, Zhiqing Sun, Yihao Feng, Keyang Xu, Yuanhan Zhang, Di Fu, Chunyuan Li, Alexander Hauptmann, Yonatan Bisk, Yiming Yang</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>用 GPT-4V 蒸馏出的详细视频 caption 当作视频内容的代理证据，让纯文本 LLM 给视频 QA 回答打事实性分数，再拿这个便宜奖励做 DPO，把视频 LMM 的幻觉压下去。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>对齐视频大多模态模型（video LMM）卡在一个具体的地方：拿不到可扩展的偏好信号。RLHF 和 DPO 在纯语言上已经被验证有效，但要把它们搬到视频指令跟随任务上，你需要一个奖励系统能判断&quot;这个回答相对视频而言是不是编的&quot;。而幻觉恰恰是视频 LMM 最主要的失效模式——模型会描述视频里根本没有的物体、动作、计数。</p><p>为什么难扩展，论文给了两个可核实的成本数字。LLaVA-RLHF 收集 10k 条人工评估实例花了约 $3000。用 GPT-4V 直接看帧来蒸馏偏好（如 Silkie 的做法）虽然自动化，但视频要送多帧，按 $30 每百万 token 计价且推理慢，规模化不现实。另一条路是用 SFT 模型自评（Ahn et al. 2024），但 SFT 模型本身有没有能力判断事实性，从未被确证。解决这个问题的价值很直接：它决定了视频 LMM 能否走上语言模型那条&quot;用可扩展的自动反馈持续对齐&quot;的路径。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>视频-文本数据集</strong>方面，WebVid、InternVid、ActivityNet-QA、TGIF-QA、MSR-VTT 提供的多是短句或关键词级别的 caption；HowToCaption 用 ASR 抽文本，但音频与画面不匹配或缺失时会对不上；Video-ChatGPT 用人力做出高质量视频指令，但局限在 ActivityNet 域内、只有 100k 对。共同的缺口是：没有足够详细、能当作&quot;视频内容替身&quot;来用的 caption。</p><p><strong>LMM 偏好建模</strong>方面，LLaVA-RLHF 把 caption 信息加进奖励模型以改善事实性判断，VLM-RLAIF 用 AI 反馈做 RL 提升视频 LMM，Silkie 与 Gunjal et al. 在图像域上用 GPT-4V 对一组模型输出蒸馏奖励做 DPO，Zhao et al. 用 ChatGPT 基于详细图像描述构造正负样本对。这些工作要么停在图像域，要么在视频域用了昂贵或未经验证的奖励源。论文的定位是：把 DPO 扩展到视频 LMM 对齐，并把详细 caption 作为事实性证据显式引入奖励环节。</p><p>论文还对<strong>评测本身</strong>提出了批评。现有视频 QA benchmark（MSVD-QA、MSRVTT-QA、TGIF-QA）的问题是自动生成的，可能语法不通甚至无意义；答案被限制成单个词，不足以评估长文本生成模型的有用性与幻觉。这个缺口后来直接催生了它自己的新评测集。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>先接受一个约束：直接让模型看视频帧来判断事实性，成本主要来自&quot;多帧 × 视觉模型&quot;这个乘积。这个乘积没法在保持视觉输入的前提下降下来。</p><p>那么换个方向：如果有一段足够详细、覆盖时序动态、世界知识、物体属性、空间关系的文字描述，它在多大程度上能替代帧？这不是新想法——LLaVA-RLHF 已经把 caption 加进奖励模型辅助事实性判断。但它是作为<strong>辅助信息</strong>加进去的，视觉输入仍在。把它推到极端：干脆完全去掉视觉输入，让纯文本 LLM 只看 caption 打分。</p><p>这个替换只有在两个条件下成立：caption 质量足够高（否则代理失真），以及&quot;caption 代理&quot;与&quot;直接看帧&quot;的评判结果确实一致（否则奖励是错的）。第一个条件靠数据工程解决——用 GPT-4V 加精心设计的 prompt 大规模蒸馏。第二个条件必须被实验验证，不能假设，所以论文专门用一整节做了对齐性检验。</p><p>一旦这两点成立，成本结构就彻底变了：caption 是一次性成本，之后每一条偏好数据只需要一次纯文本 LLM 调用。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>判断&quot;回答有没有编&quot;这件事，需要的不是像素，而是一份可信的事实清单。把视频压缩成一段足够详细的文字描述，事实性判断就从多模态问题退化成纯文本比对问题，而后者既便宜又是语言模型最擅长的。剩下唯一要证明的是：这次压缩没有丢掉判断所需的关键信息。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以一段&quot;人在太空站里倒果汁&quot;的视频、问题&quot;液体离开瓶子后是怎么运动的&quot;为例。</p><ol><li><strong>Caption 蒸馏（ShareGPTVideo）</strong>：从 WebVid（400k）、VIDAL（450k）、ActivityNet（50k）采样共 900k 视频。每个视频均匀抽 10 帧拼成序列送给 GPT-4V，prompt 要求覆盖时序动态、世界知识、物体属性、空间关系、美学评估等维度，生成一段连贯的详细 caption。</li><li><strong>SFT 数据生成</strong>：从三个源分别取 20k / 30k / 30k 条 caption，用 ChatGPT 对每条生成 3 组问答，得到 240k 条指令数据。因为问答直接从 caption 派生，指令数据与视频内容天然事实一致。</li><li><strong>候选采样</strong>：从上述数据中随机取 20k 条指令对，让 SFT 模型在 temperature 1.0 下对每对生成 6 个回答，得到 120k 条待评估问答。</li><li><strong>打分</strong>：把「问题 + 真值答案 + 模型预测 + 详细 caption（作为支撑证据）」送给 ChatGPT，先输出一段自然语言解释作为 chain-of-thought，再给出 1–5 的数值分，衡量事实对齐与整体质量。</li><li><strong>构造偏好对</strong>：每个视频-问题对里，随机取一个分数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> 的作为正例、一个低于 3 的作为负例；如果 6 个回答全在 3 以上或全在 3 以下则整条丢弃。最终得到约 17k 条 DPO 训练实例。成本低于 $20（按每百万 token $1.5 计价）。</li><li><strong>训练</strong>：backbone 用 Video-LLaVA（LanguageBind 编码器 + 两层 MLP projector + Vicuna）。预训练阶段用 650k ALLaVA 图像 caption 加 900k 蒸馏视频 caption，冻结视觉编码器、微调 projector 与 LLM（lr 2e-5，batch 128）。SFT 阶段用 600k ALLaVA 图像指令加自生成的 240k 视频指令（lr 5e-6，batch 128）。DPO 阶段用 17k 偏好数据训 3 个 epoch，lr 5e-7，batch 128，约 420 步，8 张 A100。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>DPO 的目标函数直接照搬到视频条件下，只是把条件从&quot;问题&quot;扩展成&quot;问题 + 视频&quot;：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">DPO</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4em;vertical-align:-0.95em;"></span><span class="mord">−</span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathcal mtight" style="margin-right:0.0822em;">V</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">x</span><span class="mpunct mtight">,</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1645em;"><span style="top:-2.357em;margin-left:-0.0359em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mpunct mtight">,</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3488em;margin-left:-0.0359em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1512em;"><span></span></span></span></span></span></span><span class="mclose mtight">)</span><span class="mrel mtight">∼</span><span class="mord mtight"><span class="mord mathcal mtight" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3567em;margin-left:-0.0278em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">D</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">O</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1433em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">[</span></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">(</span></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">)</span></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">]</span></span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0822em;">V</span></span></span></span> 是视频、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> 是问题、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是正负回答，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span></span></span></span> 是 logistic 函数，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.1</span></span></span></span>，policy 与 reference 都从 SFT 权重初始化。</p><p>给数学背景较弱的读者补一句直觉：括号里的两项是&quot;策略相对参考模型对正例的对数似然提升&quot;减去&quot;对负例的提升&quot;。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mopen">(</span><span class="mord">⋅</span><span class="mclose">)</span></span></span></span> 把这个差值压到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">)</span></span></span></span> 再取对数，于是优化的效果是<strong>拉大正负例之间的相对似然差</strong>，而不是无限抬高正例的绝对概率。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span> 控制策略允许偏离参考模型多远：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span> 越小越容易跑远。之所以能省掉显式奖励模型，是因为 DPO 的推导表明最优策略与奖励之间存在闭式对应，于是奖励项可以被消去，只剩下这个成对比较的分类损失。本文的贡献不在这个式子本身，而在于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">D</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">O</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 里的偏好标签是怎么以极低成本产生的。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：caption 代理与直接看帧的评判一致吗？</strong> 从 WebVid、VIDAL、ActivityNet 各取 200 个视频，每个配一个问题和两个 SFT 模型预测（一个被 ChatGPT 偏好、一个不被偏好），共 1200 例，用 gpt-4-vision-preview 直接看帧打分做对照（API 过滤后各剩 196 / 151 / 143 个）。ChatGPT 与 GPT-4V 的平均分分别是 2.9 与 3.5，说明 GPT-4V 略偏宽松；Pearson 相关系数 0.47（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.01</span></span></span></span>），属中等正相关；超过 75% 的 ChatGPT 分落在 GPT-4V 分的一个标准差（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.31</span></span></span></span>）内；排除平局后偏好一致率超过 70%。作者的措辞是&quot;cautiously support&quot;，没有把中等相关说成强对齐，这一点值得肯定。</p><p><strong>问题二：DPO 有没有用？</strong> 在 MSVD-QA / MSRVTT-QA / TGIF-QA 上用 gpt-3.5-turbo-0613 评测，LLaVA-Hound-DPO 平均准确率 70.75%，SFT 版本 62.65%，提升 8.1 个百分点，同时超过用 RL 路线的 VLM-RLAIF。论文还专门做了一个容易被忽视的对照：同样一批模型在 gpt-3.5-turbo-0301 / 0613 / 1106 三个版本下评测，绝对分数差异极大（例如 DPO 版本分别是 82.03 / 70.75 / 77.61），但模型间的相对排名基本稳定。由此提出一个方法学建议：论文必须显式声明所用的 ChatGPT 版本。</p><p><strong>问题三：现有 benchmark 够用吗？</strong> 错误分析发现两个结构性问题：自动生成的问题可能语法不通甚至无意义；真值答案被限制成单个词，无法评估长文本生成里的有用性和幻觉。于是论文对同一批视频用详细 caption 生成新的长文本 QA 作为新评测集。在这套评测下模型间区分度更好，且 out-of-domain 提升更显著——例如 SSV2-QA 上 SFT 的 35.07% 提到 DPO 的 48.89%，MSRVTT-QA 57.82% 提到 68.29%。</p><p><strong>问题四：增益到底来自哪？</strong> 一组消融把因果链拆开。只用图像指令微调的基线在 in-domain 上与完整 SFT 相当（65.97% vs 66.06%），但 out-of-domain 明显更差（49.32% vs 56.50%），说明视频 QA 训练确实带来泛化。把自生成视频 QA 换成 Video-ChatGPT 数据集，平均准确率只差 0.2%，说明生成数据质量与既有数据相当；既然 SFT 数据质量相近，那么相对 Video-LLaVA 的大幅领先应主要归因于大规模 caption 预训练。DPO 阶段解冻 MLP 会显著掉点（但仍好于 SFT）；lr 从 5e-7 降到 3e-7 也掉点。用 self-play（真值答案当正例、模型输出当负例）替代奖励模型，准确率比 SFT 还低约 3%，说明引入奖励模型是有价值的。DPO 模型当 ranker 用（对 SFT 的候选重排）在 64 候选时准确率约 62%，仍低于直接用它生成的 68.29%；而 SFT 在 temperature 1.0 下只有 43.3%，贪心解码 57.8%。这个结果与数学任务上的 V-STaR 结论相反，作者归因于任务差异。训练轮数上，性能在约 2.5 epoch（约 350 步）达峰。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：视频 LMM 对齐的瓶颈是可扩展的事实性偏好信号，人工标注和 GPT-4V 看帧都太贵。本文用 GPT-4V 蒸馏出 900k 条详细视频 caption（ShareGPTVideo），把 caption 当作视频内容的代理证据，让纯文本 ChatGPT 对视频 QA 回答打 1–5 分并给出解释。这套奖励与 GPT-4V 直接看帧的评判呈中等正相关（PCC 0.47）、偏好一致率超 70%，而成本从 $3000 级降到 $20 级。用约 17k 条偏好对做 DPO，LLaVA-Hound-DPO 相对 SFT 在三个视频 QA benchmark 上平均提升 8.1 个百分点。论文同时指出现有 benchmark 的单词答案和自动生成问题不足以评估长文本幻觉，并给出基于详细 caption 的新评测集。</p><p><strong>3 句话版</strong>：把视频压成足够详细的文字，事实性判断就从多模态问题退化成纯文本问题，成本降两个数量级。这个替换的合法性被显式验证过，而不是假设。DPO 在视频 LMM 上首次跑通，且 DPO 模型直接生成比当 ranker 用更好。</p><p><strong>1 句话版</strong>：详细 caption 是视频内容的廉价代理，用它喂出来的语言模型奖励足以支撑视频 LMM 的 DPO 对齐。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最关键的假设是：<strong>GPT-4V 生成的详细 caption 完整保留了判断回答事实性所需的信息</strong>。奖励的正确性、DPO 训练信号的正确性、乃至新评测集的有效性，全部建立在这一点上。</p><p>它在实践中可能不成立，而且失效方向是系统性的而非随机的。caption 是 GPT-4V 从 10 帧均匀采样中生成的，那些没有落在采样帧上的事件不会进入 caption；细粒度时序顺序、快速动作、精确计数、以及需要连续观察才能确认的因果关系，都是压缩过程中最容易丢的东西。更麻烦的是：<strong>丢失的信息恰好与幻觉最容易发生的地方重合</strong>。当模型编造一个 caption 里没提到的细节时，纯文本评判器只能看到&quot;caption 没说&quot;，它无法区分&quot;视频里确实没有&quot;和&quot;caption 漏了&quot;。前者应判幻觉，后者不该判。这会给奖励引入一个偏向：惩罚那些描述了真实但未被 caption 覆盖的细节的回答，从而把模型往&quot;只说 caption 风格的安全内容&quot;上训。</p><p>论文提供的证据是那次 1200 例的对齐性检验：PCC 0.47、75% 在一个标准差内、偏好一致率超 70%。这些数字支持&quot;大体一致&quot;，但 0.47 只是中等相关，且 GPT-4V 系统性给分更高（3.5 vs 2.9）这一偏差本身就提示两者的判断依据不同。缺的证据是：没有按&quot;回答是否包含 caption 未覆盖的细节&quot;分层，去看两个评判器在这个子集上的分歧有多大。而这正是上述失效模式最该被测量的地方。作者也承认对齐还可以通过 Likert 量表或 GPT-4 评判进一步改进，属于对同一问题的间接承认。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、不需要复现 900k caption 蒸馏的验证，直接针对上面那个最脆弱的假设。</p><ul><li><strong>数据</strong>：取 300 个有人工详细标注的视频（例如从带密集时序标注的公开数据集里选），每个生成一段 GPT-4V 风格的 10 帧 caption。</li><li><strong>构造</strong>：对每个视频人工或半自动构造两类模型回答——(a) 内容真实但 caption 未覆盖的细节；(b) 内容虚假的幻觉细节。每类各 300 条。</li><li><strong>测量</strong>：分别用「纯文本 LLM + caption」和「多模态模型 + 全部帧」给这 600 条打分，统计两类回答上的分数差与判罚率。</li><li><strong>判据</strong>：若 (a) 类回答被 caption 代理评判器系统性低分（判罚率接近 (b) 类），则代理奖励确实惩罚了真实但未覆盖的内容，论文的奖励存在可测量的系统偏差，DPO 训出的模型应表现为&quot;描述更保守&quot;；若 (a) 类判罚率显著低于 (b) 类，代理假设在这一维度上站得住。这个实验不需要训练任何模型，一周内可完成。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是给出一个<strong>替代解释</strong>：8.1 个百分点的提升可能主要来自&quot;回答风格向评判器偏好靠拢&quot;，而不是&quot;幻觉真的减少了&quot;。</p><p>理由有三层。第一，DPO 的偏好标签由 ChatGPT 产生，而主要评测（包括论文自建的新评测集）也由 ChatGPT 打分——训练信号与评测信号同源，模型完全可能学到评判器的风格偏好（长度、结构、措辞、覆盖广度）而非事实性。第二，论文自己的数据支持这条解释的可行性：不同 ChatGPT 版本下绝对分数波动巨大（DPO 版本从 70.75 到 82.03），说明分数对评判器的表面偏好高度敏感。第三，DPO 当 ranker 用只到约 62%、直接生成到 68.29%，这个差距用&quot;学到了生成风格&quot;比用&quot;学到了事实判别能力&quot;更好解释——如果学到的真是判别能力，当 ranker 用应该更强而不是更弱。</p><p>具体实验：构造一个与训练奖励<strong>完全解耦</strong>的评测。取一批视频，人工标注每段视频中可被客观核实的原子事实（物体存在、计数、动作顺序），让 SFT 与 DPO 模型自由生成描述，然后用规则或人工核对每条生成中的事实错误率与遗漏率，同时记录回答长度与句式分布。如果 DPO 版本的事实错误率没有显著下降，但长度与句式明显向 caption 风格靠拢，那么 8.1 个百分点就应重新解释为风格对齐而非幻觉削减。论文当前的错误分析只给了两个定性样例，不足以排除这个替代解释。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：整套方法把视频压成一段静态文字，压缩是一次性的、与问题无关的。这决定了它对&quot;caption 没覆盖的细节&quot;天然失明，也决定了奖励信号的上限就是 caption 的覆盖上限。加长 caption 只能线性缓解，不改变性质。</p><p><strong>新 framing</strong>：把事实性核验从&quot;一次性压缩 + 文本比对&quot;改造成&quot;<strong>按需的视觉取证</strong>&quot;。当评判器面对一条回答时，不是去查一份固定的 caption，而是把回答里的每个原子断言转成一个可定位的核验查询（&quot;第几秒左右画面里有没有 X&quot;），只对这些查询检索并送入少量相关帧。这样视觉调用次数与断言数成正比而非与视频长度成正比，成本仍然可控，但覆盖面不再受限于预生成 caption。评判的语义也变了：从&quot;caption 里有没有提&quot;变成&quot;能不能在视频里找到证据&quot;，直接消除了 §9 里那个把&quot;未覆盖&quot;误判成&quot;虚假&quot;的偏差。</p><p><strong>可借鉴的相邻领域工具</strong>：开放域问答里的 retrieval-augmented verification 与 claim decomposition（把长回答拆成可独立核验的原子 claim 是成熟做法）；视频时序定位（temporal grounding）模型用于把 claim 映射到时间区间；主动学习中的信息增益准则用于决定&quot;哪些 claim 值得花视觉预算去核验&quot;。</p><p><strong>第一个实验</strong>：在 §10 那套 600 条回答上，比较三种评判器——固定 caption 代理、全帧多模态、以及按需取证（claim 分解 + 时序定位 + 少量帧核验）。测两件事：与人工事实标注的一致性，以及平均视觉 token 消耗。如果按需取证能在消耗远低于全帧的前提下把一致性拉到接近全帧水平，尤其是把 §9 中 (a) 类回答的误判率压下去，那么它就可以替换掉 caption 代理成为新的奖励源，且这套核验器本身可以直接复用为一个更可信的视频 LMM 评测协议。</p>',50)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
